insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g4_pe_v1'
from (values
('116.16.b.1.A',3,'In a game of basketball, which locomotor skill is used to change direction quickly?','["cutting", "kneeling", "napping", "crawling"]'::jsonb,0,'Cutting is a quick directional change.','original'),
('116.16.b.1.A',3,'Using the correct technique for running means your foot lands under...','["your head", "your body", "your hands", "your knees locked"]'::jsonb,1,'Landing under the hips improves control.','original'),
('116.16.b.1.B',3,'In a long jump, you should swing your arms forward and land with...','["your head", "stiff legs", "both feet and bent knees", "your hands"]'::jsonb,2,'A controlled two-foot landing is safest.','original'),
('116.16.b.1.B',3,'A full turn jump means you jump and rotate...','["a quarter turn", "backward only", "not at all", "all the way around in the air"]'::jsonb,3,'A full turn is 360 degrees.','original'),
('116.16.b.1.C',3,'Cross lateralization during a coordination drill means moving...','["opposite arm and leg together", "nothing", "only your arms", "only your legs"]'::jsonb,0,'Opposite sides work together.','original'),
