('116.16.b.14',3,'When a task is hard, perseverance means you...','["quit", "blame others", "keep trying with a plan", "complain"]'::jsonb,2,'Perseverance is sustained effort.','original'),
('116.16.b.14',3,'A person shows perseverance when they...','["avoid challenge", "give up", "never practice", "practice a challenging skill each day"]'::jsonb,3,'Daily effort builds skill.','original'),
