('116.16.b.16.A',3,'Vigorous physical activity includes...','["reading", "napping", "watching TV", "running or swimming laps"]'::jsonb,3,'It raises heart rate a lot.','original'),
('116.16.b.16.B',3,'Participating in a variety of community activities, such as joining a youth sports league, helps you...','["stay active and make friends", "avoid people", "become bored", "stay inside"]'::jsonb,0,'Community activities build health and friendships.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
